# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: scripts/deploy-logging-tracing.sh
#!/usr/bin/env bash
set -Eeuo pipefail

export OBS_NAMESPACE="${OBS_NAMESPACE:-ibts-observability}"
NS="$OBS_NAMESPACE"
echo "==> Targeted Namespace: ${NS}"

# Same fallback as before. Use a password without double quotes or backslashes
# (it is written into a YAML values file below).
if [[ -z "${TF_VAR_grafana_admin_password:-}" ]]; then
  echo "  [WARN] TF_VAR_grafana_admin_password not set -- using dev fallback password"
fi
GRAFANA_PASSWORD="${TF_VAR_grafana_admin_password:-ibts-grafana-dev}"

# ---------------------------------------------------------------------
# HELPERS
# ---------------------------------------------------------------------
on_error() {
  echo "  [FAIL] Script failed -- dumping namespace state"
  kubectl get pods   -n "$NS" -o wide 2>/dev/null || true
  kubectl get pvc    -n "$NS" 2>/dev/null || true
  kubectl describe resourcequota -n "$NS" 2>/dev/null || true
  kubectl get events -n "$NS" \
    --sort-by='.lastTimestamp' 2>/dev/null | tail -25 || true
}
trap on_error ERR

# Prints the helm release status (deployed / failed / pending-install / ...)
# or nothing if no release record exists. Works for any state.
release_status() {
  local st
  st=$(helm status "$1" -n "$NS" 2>/dev/null | awk '/^STATUS:/{print $2}' || true)
  echo "$st"
}

# Fully removes a release and anything it left behind. Safe to run when
# nothing exists.
force_remove_release() {
  local rel=$1
  echo "  [CLEAN] removing release '${rel}' and leftovers"
  helm uninstall "$rel" -n "$NS" --no-hooks --wait --timeout 2m || true

  # If the release record survived (stuck pending/failed), drop helm's state
  kubectl delete secret -n "$NS" -l "owner=helm,name=${rel}" --ignore-not-found

  # Leftover workloads from an earlier failed install
  kubectl delete deploy,sts,ds,svc,cm,sa,job,cronjob,pod -n "$NS" \
    -l "app.kubernetes.io/instance=${rel}" --ignore-not-found --wait=false
  kubectl wait --for=delete pod -l "app.kubernetes.io/instance=${rel}" \
    -n "$NS" --timeout=120s 2>/dev/null || true

  if [[ -n "$(release_status "$rel")" ]]; then
    echo "  [FAIL] release '${rel}' record still exists after cleanup:"
    helm list -n "$NS" -a || true
    exit 1
  fi
}

# Only cleans a release that is BROKEN (failed / pending-*). A healthy
# 'deployed' release is left in place so the following
# 'helm upgrade --install' can apply new settings to it.
clean_if_broken() {
  local rel=$1 st
  st=$(release_status "$rel")
  if [[ -n "$st" && "$st" != "deployed" ]]; then
    echo "  [WARN] ${rel} is in state '${st}' -- cleaning before reinstall"
    force_remove_release "$rel"
  fi
}

# Prints readyReplicas for a workload, or 0 if missing / none ready
ready_replicas() {
  local out
  out=$(kubectl get "$1" "$2" -n "$NS" \
    -o jsonpath='{.status.readyReplicas}' 2>/dev/null || true)
  echo "${out:-0}"
}

# True only if Elasticsearch answers 200 on plain HTTP (not just "pod Ready")
es_http_ok() {
  local code
  code=$(kubectl exec -n "$NS" elasticsearch-master-0 -c elasticsearch -- \
    curl -s -o /dev/null -w '%{http_code}' localhost:9200 2>/dev/null || true)
  [[ "$code" == "200" ]]
}

# Call the Elasticsearch API from inside the ES pod.
# usage: es_api METHOD PATH [JSON_BODY]    -- prints the response
es_api() {
  local args=(-s -X "$1" -H 'Content-Type: application/json')
  if [[ -n "${3:-}" ]]; then
    args+=(-d "$3")
  fi
  kubectl exec -n "$NS" elasticsearch-master-0 -c elasticsearch -- \
    curl "${args[@]}" "localhost:9200$2"
  echo
}

# Same as es_api, but fails the script unless ES answers acknowledged:true
es_api_ack() {
  local out
  out=$(es_api "$@")
  echo "  $out"
  if ! grep -q '"acknowledged":true' <<< "$out"; then
    echo "  [FAIL] Elasticsearch did not acknowledge: $1 $2"
    exit 1
  fi
}

# Helm silently ignores unknown --set keys. Warn if a key pattern is not
# present anywhere in the chart's default values.
warn_if_chart_key_missing() {
  local chart=$1 version=$2 pattern=$3 vals
  vals=$(helm show values "$chart" --version "$version" 2>/dev/null || true)
  if ! grep -qiE "$pattern" <<< "$vals"; then
    echo "  [WARN] ${chart}@${version}: no match for '${pattern}' in values -- that --set key may be ignored"
  fi
}

# ---------------------------------------------------------------------
# NAMESPACE + HELM REPOS
# ---------------------------------------------------------------------
kubectl create namespace "$NS" --dry-run=client -o yaml | kubectl apply -f -

echo "==> Configuring Helm Repositories..."
helm repo add prometheus-community https://prometheus-community.github.io/helm-charts
helm repo add elastic        https://helm.elastic.co
helm repo add open-telemetry https://open-telemetry.github.io/opentelemetry-helm-charts
helm repo add jaegertracing  https://jaegertracing.github.io/helm-charts
helm repo add fluent         https://fluent.github.io/helm-charts
helm repo update

# =====================================================================
# STAGE 0: KUBE-PROMETHEUS-STACK
# The namespace LimitRange gives every container without limits 500m CPU,
# and DaemonSets pay that PER NODE, which fills the CPU limits quota.
# So explicit small limits are set here in the Helm values (persistent,
# unlike 'kubectl set resources', which the next helm upgrade overwrites).
# Pipeline: values file + upgrade --install + --wait (idempotent).
# =====================================================================
echo "==> Stage 0: kube-prometheus-stack"
clean_if_broken kube-prometheus-stack

# Webhooks are disabled below; remove stale configs from earlier runs so they
# cannot block PrometheusRule / ServiceMonitor creation.
kubectl delete mutatingwebhookconfiguration kube-prometheus-stack-admission --ignore-not-found
kubectl delete validatingwebhookconfiguration kube-prometheus-stack-admission --ignore-not-found

PROM_VALUES=$(mktemp /tmp/prom-values-XXXXXX.yaml)
cat << EOF > "$PROM_VALUES"
prometheusOperator:
  tls:
    enabled: false
  admissionWebhooks:
    enabled: false
    patch:
      enabled: false
    certManager:
      enabled: false
  resources:
    requests: {cpu: 50m, memory: 64Mi}
    limits:   {cpu: 200m, memory: 256Mi}
prometheus:
  prometheusSpec:
    retention: 30d
    resources:
      requests: {cpu: 200m, memory: 768Mi}
      limits:   {cpu: 1000m, memory: 1536Mi}
    storageSpec:
      volumeClaimTemplate:
        spec:
          storageClassName: gp3
          resources:
            requests:
              storage: 20Gi
alertmanager:
  alertmanagerSpec:
    resources:
      requests: {cpu: 25m, memory: 64Mi}
      limits:   {cpu: 100m, memory: 128Mi}
grafana:
  adminPassword: "${GRAFANA_PASSWORD}"
  persistence:
    enabled: true
    storageClassName: gp3
  resources:
    requests: {cpu: 100m, memory: 128Mi}
    limits:   {cpu: 500m, memory: 512Mi}
  sidecar:
    resources:
      requests: {cpu: 25m, memory: 64Mi}
      limits:   {cpu: 100m, memory: 128Mi}
kube-state-metrics:
  resources:
    requests: {cpu: 25m, memory: 64Mi}
    limits:   {cpu: 100m, memory: 128Mi}
prometheus-node-exporter:
  resources:
    requests: {cpu: 50m, memory: 32Mi}
    limits:   {cpu: 100m, memory: 64Mi}
EOF

helm upgrade --install kube-prometheus-stack \
  prometheus-community/kube-prometheus-stack \
  -n "$NS" --version 58.2.2 --timeout 30m --wait \
  -f "$PROM_VALUES"
rm -f "$PROM_VALUES"

kubectl get pods -n "$NS" --no-headers
kubectl describe resourcequota -n "$NS" || true

# =====================================================================
# STAGE 1: ELASTICSEARCH
# =====================================================================
echo "==> Stage 1: elasticsearch"
if es_http_ok && [[ "$(ready_replicas statefulset elasticsearch-master)" -ge 1 ]]; then
  echo "  [SKIP] elasticsearch already Ready and serving plain HTTP on :9200"
else
  if [[ -n "$(release_status elasticsearch)" ]] \
     || kubectl get sts elasticsearch-master -n "$NS" >/dev/null 2>&1; then
    echo "  [WARN] elasticsearch missing, not Ready, or not answering on HTTP -- removing and reinstalling"
    helm uninstall elasticsearch -n "$NS" --no-hooks || true
    kubectl delete sts elasticsearch-master -n "$NS" --ignore-not-found --wait=true
    # Data dir may have been initialised with security on -- start clean (dev only)
    kubectl delete pvc elasticsearch-master-elasticsearch-master-0 \
      -n "$NS" --ignore-not-found --wait=true --timeout=3m
  fi

  warn_if_chart_key_missing elastic/elasticsearch 8.5.1 'podAnnotations'

  ES_CONFIG_FILE=$(mktemp /tmp/elasticsearch-XXXXXX.yml)
  cat << 'EOF' > "$ES_CONFIG_FILE"
xpack.security.enabled: false
xpack.ml.enabled: false
EOF

  # createCert=false stops the chart injecting security/TLS env vars that
  # would override the esConfig above.
  # Do NOT set secret.enabled=false: the chart's readiness probe requires
  # ELASTIC_PASSWORD, which is only injected when the secret is enabled.
  # (With security off, Elasticsearch ignores the password.)
  #
  # podAnnotations karpenter.sh/do-not-disrupt stops Karpenter
  # consolidation from evicting the stateful ES pod.
  helm install elasticsearch elastic/elasticsearch \
    -n "$NS" --version 8.5.1 --timeout 15m --wait \
    --set replicas=1 \
    --set minimumMasterNodes=1 \
    --set esJavaOpts="-Xmx512m -Xms512m" \
    --set resources.requests.cpu=500m \
    --set resources.requests.memory=1Gi \
    --set resources.limits.cpu=1000m \
    --set resources.limits.memory=1536Mi \
    --set sysctlInitContainer.enabled=true \
    --set sysctlVmMaxMapCount=262144 \
    --set volumeClaimTemplate.storageClassName=gp3 \
    --set volumeClaimTemplate.resources.requests.storage=10Gi \
    --set nodeSelector."node\.kubernetes\.io/instance-type"=t3.large \
    --set createCert=false \
    --set protocol=http \
    --set-string 'podAnnotations.karpenter\.sh/do-not-disrupt=true' \
    --set-file esConfig."elasticsearch\.yml"="$ES_CONFIG_FILE"
  rm -f "$ES_CONFIG_FILE"

  # Fail early (with a clear message) if HTTP still doesn't work
  for i in $(seq 1 12); do
    es_http_ok && break
    echo "  [$((i*10))s] waiting for plain-HTTP 200 from elasticsearch..."
    sleep 10
  done
  es_http_ok || { echo "  [FAIL] elasticsearch is not serving plain HTTP"; exit 1; }
  echo "  [OK] elasticsearch answering on http://localhost:9200"
fi
kubectl get pods -n "$NS" -l app=elasticsearch-master --no-headers

# =====================================================================
# STAGE 2: KIBANA (plain Deployment -- the chart's pre-install hook only
# supports https, but Elasticsearch here runs http with security off)
# =====================================================================
echo "==> Stage 2: kibana"
if [[ "$(ready_replicas deployment kibana-kibana)" -ge 1 ]]; then
  echo "  [SKIP] kibana-kibana already running"
else
  # Remove leftovers from an earlier failed chart install, if any
  if [[ -n "$(release_status kibana)" ]]; then
    echo "  [WARN] removing old kibana helm release"
    helm uninstall kibana -n "$NS" --no-hooks || true
  fi
  kubectl delete job pre-install-kibana-kibana post-delete-kibana-kibana \
    -n "$NS" --ignore-not-found
  kubectl get pods -n "$NS" -o name | { grep 'pre-install-kibana' || true; } \
    | xargs -r kubectl delete -n "$NS" --ignore-not-found

  kubectl apply -n "$NS" -f - << EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: kibana-kibana
spec:
  replicas: 1
  selector:
    matchLabels:
      app: kibana
  template:
    metadata:
      labels:
        app: kibana
    spec:
      containers:
        - name: kibana
          image: docker.elastic.co/kibana/kibana:8.5.1
          env:
            - name: ELASTICSEARCH_HOSTS
              value: "http://elasticsearch-master.${NS}.svc.cluster.local:9200"
          ports:
            - containerPort: 5601
          resources:
            requests:
              cpu: 250m
              memory: 768Mi
            limits:
              cpu: 1000m
              memory: 1536Mi
          startupProbe:
            httpGet:
              path: /api/status
              port: 5601
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 60
          readinessProbe:
            httpGet:
              path: /api/status
              port: 5601
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 3
---
apiVersion: v1
kind: Service
metadata:
  name: kibana-kibana
spec:
  selector:
    app: kibana
  ports:
    - port: 5601
      targetPort: 5601
EOF
  kubectl rollout status deployment/kibana-kibana -n "$NS" --timeout=10m
fi

# =====================================================================
# STAGE 3: OPENTELEMETRY COLLECTOR
# Traces are exported to Jaeger over OTLP (the chart default was the
# 'debug' exporter, which discards everything).
# Pipeline lists are written in full because Helm REPLACES lists.
# Logs and metrics pipelines still use 'debug' for now.
# =====================================================================
echo "==> Stage 3: otel-collector"
clean_if_broken otel-collector

OTEL_VALUES=$(mktemp /tmp/otel-values-XXXXXX.yaml)
cat << EOF > "$OTEL_VALUES"
config:
  exporters:
    otlp/jaeger:
      endpoint: jaeger-collector.${NS}.svc.cluster.local:4317
      tls:
        insecure: true
  service:
    pipelines:
      traces:
        receivers: [otlp, jaeger, zipkin]
        processors: [memory_limiter, batch]
        exporters: [otlp/jaeger]
EOF

# upgrade --install so the settings apply to an existing release.
# command.name must match the binary in the contrib image.
helm upgrade --install otel-collector open-telemetry/opentelemetry-collector \
  -n "$NS" --version 0.91.0 --timeout 5m --wait \
  -f "$OTEL_VALUES" \
  --set mode=deployment \
  --set image.repository=otel/opentelemetry-collector-contrib \
  --set command.name=otelcol-contrib \
  --set resources.requests.cpu=100m \
  --set resources.requests.memory=128Mi \
  --set resources.limits.cpu=250m \
  --set resources.limits.memory=512Mi
rm -f "$OTEL_VALUES"

# =====================================================================
# STAGE 4: JAEGER
# upgrade --install (fixes apply on re-run), OTLP ports published
# on the collector Service, ES_NUM_REPLICAS=0 for single-node ES.
# =====================================================================
echo "==> Stage 4: jaeger"
clean_if_broken jaeger

echo "--- Quota before Jaeger:"
kubectl describe resourcequota -n "$NS" || true

warn_if_chart_key_missing jaegertracing/jaeger 3.0.0 'agentSidecar'
warn_if_chart_key_missing jaegertracing/jaeger 3.0.0 'usePassword'
warn_if_chart_key_missing jaegertracing/jaeger 3.0.0 'otlp'
warn_if_chart_key_missing jaegertracing/jaeger 3.0.0 'extraEnv'

# Small explicit limits keep the namespace CPU quota from being exhausted.
# query.agentSidecar.enabled=false drops the extra agent container.
helm upgrade --install jaeger jaegertracing/jaeger \
  -n "$NS" --version 3.0.0 --timeout 5m --wait \
  --set provisionDataStore.cassandra=false \
  --set provisionDataStore.elasticsearch=false \
  --set storage.type=elasticsearch \
  --set "storage.elasticsearch.host=elasticsearch-master.${NS}.svc.cluster.local" \
  --set storage.elasticsearch.port=9200 \
  --set storage.elasticsearch.usePassword=false \
  --set agent.enabled=false \
  --set query.agentSidecar.enabled=false \
  --set collector.service.otlp.grpc.name=otlp-grpc \
  --set collector.service.otlp.grpc.port=4317 \
  --set collector.service.otlp.http.name=otlp-http \
  --set collector.service.otlp.http.port=4318 \
  --set 'collector.extraEnv[0].name=ES_NUM_REPLICAS' \
  --set-string 'collector.extraEnv[0].value=0' \
  --set 'query.extraEnv[0].name=ES_NUM_REPLICAS' \
  --set-string 'query.extraEnv[0].value=0' \
  --set collector.resources.requests.cpu=100m \
  --set collector.resources.requests.memory=128Mi \
  --set collector.resources.limits.cpu=250m \
  --set collector.resources.limits.memory=256Mi \
  --set query.resources.requests.cpu=100m \
  --set query.resources.requests.memory=128Mi \
  --set query.resources.limits.cpu=250m \
  --set query.resources.limits.memory=256Mi

# Fail now if OTLP isn't published, instead of finding out later from
# a trace that never shows up.
if ! kubectl get svc jaeger-collector -n "$NS" \
     -o jsonpath='{.spec.ports[*].port}' | grep -qw 4317; then
  echo "  [FAIL] jaeger-collector Service has no port 4317 -- chart OTLP keys differ"
  echo "         Run: helm show values jaegertracing/jaeger --version 3.0.0 | grep -n -i otlp"
  exit 1
fi
echo "  [OK] jaeger-collector publishes OTLP :4317"

# =====================================================================
# STAGE 5: FLUENT-BIT (DaemonSet -- limits matter: cost is per node)
# upgrade --install, tolerate ALL taints so it runs on every node,
# Replace_Dots + Trace_Error on the ES outputs.
# =====================================================================
echo "==> Stage 5: fluent-bit"
clean_if_broken fluent-bit

warn_if_chart_key_missing fluent/fluent-bit 0.46.7 '^resources'
warn_if_chart_key_missing fluent/fluent-bit 0.46.7 '^tolerations'

# Suppress_Type_Name On: Elasticsearch 8 rejects the legacy _type field
# in bulk requests.
# Replace_Dots On: avoids field-mapping conflicts from labels such as
# app.kubernetes.io/name vs a plain "app" label.
# Trace_Error On: ES rejections show up in the Fluent Bit logs.
FB_OUTPUTS_FILE=$(mktemp /tmp/fluent-bit-outputs-XXXXXX.conf)
cat << EOF > "$FB_OUTPUTS_FILE"
[OUTPUT]
    Name  es
    Match kube.*
    Host  elasticsearch-master.${NS}.svc.cluster.local
    Port  9200
    Logstash_Format On
    Suppress_Type_Name On
    Replace_Dots On
    Trace_Error On
    Retry_Limit False

[OUTPUT]
    Name  es
    Match host.*
    Host  elasticsearch-master.${NS}.svc.cluster.local
    Port  9200
    Logstash_Format On
    Logstash_Prefix node
    Suppress_Type_Name On
    Replace_Dots On
    Trace_Error On
    Retry_Limit False
EOF

helm upgrade --install fluent-bit fluent/fluent-bit \
  -n "$NS" --version 0.46.7 --timeout 5m --wait \
  --set 'tolerations[0].operator=Exists' \
  --set resources.requests.cpu=50m \
  --set resources.requests.memory=64Mi \
  --set resources.limits.cpu=100m \
  --set resources.limits.memory=128Mi \
  --set-file config.outputs="$FB_OUTPUTS_FILE"
rm -f "$FB_OUTPUTS_FILE"

EXPECT_NODES=$(kubectl get nodes --no-headers | wc -l | tr -d ' ')
FB_READY=$(kubectl get ds fluent-bit -n "$NS" -o jsonpath='{.status.numberReady}')
if [[ "${FB_READY:-0}" == "$EXPECT_NODES" ]]; then
  echo "  [OK] fluent-bit running on all ${EXPECT_NODES} nodes"
else
  echo "  [WARN] fluent-bit ready=${FB_READY:-0} nodes=${EXPECT_NODES} (Karpenter may still be scaling)"
fi

# =====================================================================
# STAGE 6: ELASTICSEARCH REPLICAS + RETENTION
# Single-node ES can never allocate replicas (indices stay yellow), and a
# 10Gi disk fills quickly without retention.
# =====================================================================
echo "==> Stage 6: elasticsearch replicas + retention"
es_http_ok || { echo "  [FAIL] elasticsearch not answering on HTTP"; exit 1; }

# Delete log indices 7 days after creation
es_api_ack PUT /_ilm/policy/ibts-logs-7d \
  '{"policy":{"phases":{"delete":{"min_age":"7d","actions":{"delete":{}}}}}}'

# New daily indices from Fluent Bit: 0 replicas + retention policy
es_api_ack PUT /_index_template/ibts-logs \
  '{"index_patterns":["logstash-*","node-*"],"priority":200,"template":{"settings":{"index.lifecycle.name":"ibts-logs-7d","number_of_replicas":0}}}'

# =====================================================================
# STAGE 7: GRAFANA DASHBOARDS + DATASOURCES
# Each dashboard JSON becomes a ConfigMap labelled grafana_dashboard=1;
# the Grafana sidecar picks it up automatically (no pod restart).
# =====================================================================

echo "==> Stage 7: grafana dashboards + datasources"

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DASH_DIR="${REPO_ROOT}/metrics/grafana/provisioning/dashboards"
GRAFANA_FOLDER="${GRAFANA_FOLDER:-IBTS}"

shopt -s nullglob
dash_files=("${DASH_DIR}"/*.json)
shopt -u nullglob

if (( ${#dash_files[@]} == 0 )); then
  echo "  [WARN] no dashboard JSON files found in ${DASH_DIR}"
else
  for f in "${dash_files[@]}"; do
    base=$(basename "$f" .json)

    # Fail early on invalid JSON (only if jq is installed)
    if command -v jq >/dev/null 2>&1; then
      jq empty "$f" || { echo "  [FAIL] invalid JSON: $f"; exit 1; }
    fi

    # ConfigMap names must be lowercase, with '-' instead of '_'
    cm_name="grafana-dash-$(echo "$base" | tr '_A-Z' '-a-z')"

    # --server-side avoids the 256KB last-applied annotation limit that
    # large dashboard JSON files often hit with a plain 'kubectl apply'.
    kubectl create configmap "$cm_name" -n "$NS" \
        --from-file="${base}.json=${f}" --dry-run=client -o yaml \
      | kubectl label    --local -f - grafana_dashboard=1 -o yaml \
      | kubectl annotate --local -f - "grafana_folder=${GRAFANA_FOLDER}" -o yaml \
      | kubectl apply -n "$NS" --server-side --force-conflicts -f -

    echo "  [OK] dashboard loaded: ${base}"
  done
fi

# Jaeger datasource, pointing at the in-cluster service. The repo's
# jaeger.yml points at the docker-compose host 'ibts-jaeger', which does
# not exist in this cluster. Prometheus is already provisioned by the chart.
kubectl apply -n "$NS" -f - << EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: grafana-ds-jaeger
  labels:
    grafana_datasource: "1"
data:
  jaeger-datasource.yaml: |-
    apiVersion: 1
    datasources:
      - name: Jaeger
        uid: jaeger
        type: jaeger
        access: proxy
        url: http://jaeger-query.${NS}.svc.cluster.local:80
        isDefault: false
EOF

echo "  [OK] dashboards + Jaeger datasource applied"
kubectl get cm -n "$NS" -l grafana_dashboard=1